#pragma once
#include <string>

namespace auth {

const char* const USER_FILE = "data/users.json";
const char* const SESSION_FILE = "logs/session_state.json";

std::string sha256Hex(const std::string& data);
std::string makeSalt();
std::string hashPassword(const std::string& password, const std::string& salt);

bool userExists(const std::string& username);
bool registerUser(const std::string& username, const std::string& password);
bool loginUser(const std::string& username, const std::string& password);

void ensureUsersFile();
void saveSession(const std::string& username);

}

#include "auth.hpp"

#include <cstdint>
#include <fstream>
#include <random>
#include <sstream>
#include <vector>

namespace auth {

namespace {

uint32_t rotr(uint32_t x, uint32_t n) { return (x >> n) | (x << (32 - n)); }

struct User {
    std::string username;
    std::string salt;
    std::string hash;
};

std::string jsonEscape(const std::string& s) {
    std::string out;
    for (char c : s) {
        if (c == '"' || c == '\\') out.push_back('\\');
        out.push_back(c);
    }
    return out;
}

std::string readFile(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

std::vector<User> loadUsers(const std::string& path) {
    std::string content = readFile(path);
    std::vector<User> users;
    size_t pos = 0;
    while ((pos = content.find('{', pos)) != std::string::npos) {
        size_t end = content.find('}', pos);
        if (end == std::string::npos) break;
        std::string obj = content.substr(pos, end - pos + 1);
        auto grab = [&](const std::string& key) -> std::string {
            std::string pat = "\"" + key + "\":\"";
            size_t p = obj.find(pat);
            if (p == std::string::npos) return "";
            p += pat.size();
            size_t q = obj.find('"', p);
            if (q == std::string::npos) return "";
            return obj.substr(p, q - p);
        };
        User u;
        u.username = grab("username");
        u.salt = grab("salt");
        u.hash = grab("hash");
        if (!u.username.empty()) users.push_back(u);
        pos = end + 1;
    }
    return users;
}

void saveUsers(const std::string& path, const std::vector<User>& users) {
    std::ofstream out(path, std::ios::trunc);
    out << "[";
    for (size_t i = 0; i < users.size(); ++i) {
        if (i) out << ",";
        out << "\n  {\"username\":\"" << jsonEscape(users[i].username)
            << "\",\"salt\":\"" << jsonEscape(users[i].salt)
            << "\",\"hash\":\"" << jsonEscape(users[i].hash) << "\"}";
    }
    if (!users.empty()) out << "\n";
    out << "]\n";
}

}  // namespace

std::string sha256Hex(const std::string& msg) {
    static const uint32_t k[64] = {
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
        0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
        0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
        0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
        0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
        0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
        0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
        0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2};

    uint32_t h[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
                     0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};

    std::vector<uint8_t> data(msg.begin(), msg.end());
    uint64_t bitlen = static_cast<uint64_t>(data.size()) * 8;
    data.push_back(0x80);
    while (data.size() % 64 != 56) data.push_back(0);
    for (int i = 7; i >= 0; --i) data.push_back((bitlen >> (i * 8)) & 0xff);

    for (size_t off = 0; off < data.size(); off += 64) {
        uint32_t w[64];
        for (int i = 0; i < 16; ++i) {
            w[i] = (data[off + i * 4] << 24) | (data[off + i * 4 + 1] << 16) |
                   (data[off + i * 4 + 2] << 8) | data[off + i * 4 + 3];
        }
        for (int i = 16; i < 64; ++i) {
            uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
            uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        }
        uint32_t a = h[0], b = h[1], c = h[2], d = h[3];
        uint32_t e = h[4], f = h[5], g = h[6], hh = h[7];
        for (int i = 0; i < 64; ++i) {
            uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            uint32_t ch = (e & f) ^ (~e & g);
            uint32_t t1 = hh + S1 + ch + k[i] + w[i];
            uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = S0 + maj;
            hh = g; g = f; f = e; e = d + t1;
            d = c; c = b; b = a; a = t1 + t2;
        }
        h[0] += a; h[1] += b; h[2] += c; h[3] += d;
        h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }

    static const char* hx = "0123456789abcdef";
    std::string out;
    out.reserve(64);
    for (int i = 0; i < 8; ++i) {
        for (int j = 7; j >= 0; --j) {
            uint8_t byte = (h[i] >> (j * 4)) & 0xf;
            out.push_back(hx[byte]);
        }
    }
    return out;
}

std::string makeSalt() {
    std::random_device rd;
    std::mt19937_64 gen(rd());
    std::uniform_int_distribution<int> dist(0, 255);
    static const char* hx = "0123456789abcdef";
    std::string s;
    s.reserve(32);
    for (int i = 0; i < 16; ++i) {
        unsigned b = static_cast<unsigned>(dist(gen));
        s.push_back(hx[b >> 4]);
        s.push_back(hx[b & 0xf]);
    }
    return s;
}

std::string hashPassword(const std::string& password, const std::string& salt) {
    return sha256Hex(salt + password);
}

bool userExists(const std::string& username) {
    for (const User& u : loadUsers(USER_FILE)) {
        if (u.username == username) return true;
    }
    return false;
}

bool registerUser(const std::string& username, const std::string& password) {
    std::vector<User> users = loadUsers(USER_FILE);
    for (const User& u : users) {
        if (u.username == username) return false;
    }
    User u;
    u.username = username;
    u.salt = makeSalt();
    u.hash = hashPassword(password, u.salt);
    users.push_back(u);
    saveUsers(USER_FILE, users);
    return true;
}

bool loginUser(const std::string& username, const std::string& password) {
    for (const User& u : loadUsers(USER_FILE)) {
        if (u.username == username) {
            return u.hash == hashPassword(password, u.salt);
        }
    }
    return false;
}

void ensureUsersFile() {
    std::ifstream in(USER_FILE);
    if (!in.good()) {
        std::ofstream out(USER_FILE, std::ios::trunc);
        out << "[]\n";
    }
}

void saveSession(const std::string& username) {
    std::ofstream out(SESSION_FILE, std::ios::trunc);
    out << "{\"last_user\": \"" << jsonEscape(username) << "\"}\n";
}

}  // namespace auth

