#include "friends.hpp"

#include <fstream>
#include <sstream>

namespace friends {

std::string fileFor(const std::string& username) {
    return "data/friends_" + username + ".json";
}

namespace {

std::string readFile(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

std::string jsonEscape(const std::string& s) {
    std::string out;
    for (char c : s) {
        if (c == '"' || c == '\\') out.push_back('\\');
        out.push_back(c);
    }
    return out;
}

}  // namespace

std::vector<Friend> list(const std::string& username) {
    std::string content = readFile(fileFor(username));
    std::vector<Friend> result;
    size_t pos = 0;
    while ((pos = content.find('{', pos)) != std::string::npos) {
        size_t end = content.find('}', pos);
        if (end == std::string::npos) break;
        std::string obj = content.substr(pos, end - pos + 1);
        auto grab = [&](const std::string& key) -> std::string {
            std::string pat = "\"" + key + "\"";
            size_t p = obj.find(pat);
            if (p == std::string::npos) return "";
            p = obj.find(':', p + pat.size());
            if (p == std::string::npos) return "";
            ++p;
            while (p < obj.size() && (obj[p] == ' ' || obj[p] == '\t')) ++p;
            if (p >= obj.size() || obj[p] != '"') return "";
            ++p;
            size_t q = obj.find('"', p);
            if (q == std::string::npos) return "";
            return obj.substr(p, q - p);
        };
        Friend f;
        f.user = grab("user");
        f.status = grab("status");
        if (f.status.empty()) f.status = "offline";
        if (!f.user.empty()) result.push_back(f);
        pos = end + 1;
    }
    return result;
}

void save(const std::string& username, const std::vector<Friend>& entries) {
    std::ofstream out(fileFor(username), std::ios::trunc);
    out << "[";
    for (size_t i = 0; i < entries.size(); ++i) {
        if (i) out << ",";
        out << "\n  {\"user\": \"" << jsonEscape(entries[i].user)
            << "\", \"status\": \"" << jsonEscape(entries[i].status) << "\"}";
    }
    if (!entries.empty()) out << "\n";
    out << "]\n";
}

bool add(const std::string& username, const std::string& friendName) {
    std::vector<Friend> entries = list(username);
    for (const Friend& f : entries) {
        if (f.user == friendName) return false;
    }
    Friend f;
    f.user = friendName;
    f.status = "offline";
    entries.push_back(f);
    save(username, entries);
    return true;
}

bool remove(const std::string& username, const std::string& friendName) {
    std::vector<Friend> entries = list(username);
    for (size_t i = 0; i < entries.size(); ++i) {
        if (entries[i].user == friendName) {
            entries.erase(entries.begin() + static_cast<long>(i));
            save(username, entries);
            return true;
        }
    }
    return false;
}

}  // namespace friends

