#include <iostream>
#include <string>
#include <vector>

#include "auth.hpp"
#include "friends.hpp"

namespace {

std::string prompt(const std::string& label) {
    std::cout << label << std::flush;
    std::string value;
    std::getline(std::cin, value);
    return value;
}

void doRegister() {
    std::string username = prompt("Username: ");
    std::string password = prompt("Password: ");
    std::string confirm = prompt("Password: ");

    if (username.empty()) {
        std::cout << "Username cannot be empty\n";
        return;
    }
    if (password != [secret redacted]
        std::cout << "Passwords do not match\n";
        return;
    }
    if (!auth:[secret redacted]
        std::cout << "Username already exists\n";
        return;
    }
    std::cout << "Registration successful\n";
}

bool doLogin() {
    std::string username = prompt("Username: ");
    std::string password = prompt("Password: ");

    if (auth:[secret redacted]
        auth:[secret redacted]
        std::cout << "Welcome " << username << "\n";
        return true;
    }
    std::cout << "Invalid username or password\n";
    return false;
}

void printFriendMenu() {
    std::cout << "[A] Add Friend\n";
    std::cout << "[R] Remove Friend\n";
    std::cout << "[L] List Friends\n";
    std::cout << "[C] Choose Friend\n";
    std::cout << "[Q] Logout\n";
}

void friendMenu(const std::string& username) {
    printFriendMenu();
    while (true) {
        std::string action = prompt("Action: ");
        if (action == "A" || action == "a") {
            std::string name = prompt("Username: ");
            if (friends::add(username, name)) {
                std::cout << "Friend added\n";
            } else {
                std::cout << "Friend already exists\n";
            }
        } else if (action == "R" || action == "r") {
            std::string name = prompt("Username: ");
            if (friends::remove(username, name)) {
                std::cout << "Friend removed\n";
            } else {
                std::cout << "Friend not found\n";
            }
        } else if (action == "L" || action == "l") {
            std::vector<friends::Friend> entries = friends::list(username);
            if (entries.empty()) {
                std::cout << "No friends\n";
            }
            for (const friends::Friend& f : entries) {
                std::cout << "  - " << f.user << " [" << f.status << "]\n";
            }
        } else if (action == "C" || action == "c") {
            std::string name = prompt("Friend ID: ");
            std::cout << "--- Chat with " << name << " ---\n";
            while (true) {
                std::string line = prompt("");
                if (line == "/back") break;
            }
        } else if (action == "Q" || action == "q") {
            std::cout << "Logged out\n";
            return;
        } else {
            std::cout << "Invalid choice\n";
        }
    }
}

int selftestFriendMenu() {
    std::string username = auth::lastSessionUser();
    std::vector<friends::Friend> entries = friends::list(username);
    std::cout << "{\"user\": \"" << username << "\", \"friends\": [";
    for (size_t i = 0; i < entries.size(); ++i) {
        if (i) std::cout << ", ";
        std::cout << "{\"user\": \"" << entries[i].user << "\", \"status\": \""
                  << entries[i].status << "\"}";
    }
    std::cout << "]}\n";
    return 0;
}

}  // namespace

int main(int argc, char** argv) {
    if (argc > 1 && std::string(argv[1]) == "--version") {
        std::cout << "1.0.0" << std::endl;
        return 0;
    }
    if (argc > 2 && std::string(argv[1]) == "--selftest" &&
        std::string(argv[2]) == "friend-menu") {
        return selftestFriendMenu();
    }

    auth:[secret redacted]
    std::cout << "=== Chat App v1.0.0 ===\n";
    std::cout << "[1] Register\n";
    std::cout << "[2] Login\n";
    std::cout << "[3] Exit\n";

    while (true) {
        std::string action = prompt("Action: ");
        if (action == "1") {
            doRegister();
        } else if (action == "2") {
            if (doLogin()) {
                std::string username = auth::lastSessionUser();
                friendMenu(username);
                std::cout << "=== Chat App v1.0.0 ===\n";
                std::cout << "[1] Register\n";
                std::cout << "[2] Login\n";
                std::cout << "[3] Exit\n";
            }
        } else if (action == "3") {
            std::cout << "Bye\n";
            break;
        } else {
            std::cout << "Invalid choice\n";
        }
    }
    return 0;
}

