std::vector<Message> loadHistory(const std::string& user, const std::string& friendName);
void appendMessage(const std::string& user, const std::string& friendName, const Message& m);
void clearHistory(const std::string& user, const std::string& friendName);

std::vector<std::string> loadBotReplies();

