#include "chat.hpp"

#include <cstdlib>
#include <ctime>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>

#if !defined(_WIN32)
#include <unistd.h>
#endif

namespace chat {

namespace {

std::string readFile(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

bool stdinIsTerminal() {
#if defined(_WIN32)
    return true;
#else
    return isatty(fileno(stdin)) != 0;
#endif
}

void ensureDir(const std::string& user) {
    std::error_code ec;
    std::filesystem::create_directories("data/history/" + user, ec);
}

}  // namespace

std::string nowIso8601() {
    std::time_t t = std::time(nullptr);
    std::tm tmv{};
#if defined(_WIN32)
    localtime_s(&tmv, &t);
#else
    localtime_r(&t, &tmv);
#endif
    char buf[32];
    std::strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tmv);
    return buf;
}

std::string historyPath(const std::string& user, const std::string& friendName) {
    return "data/history/" + user + "/" + friendName + ".log";
}

std::vector<Message> loadHistory(const std::string& user, const std::string& friendName) {
    std::vector<Message> out;
    std::istringstream in(readFile(historyPath(user, friendName)));
    std::string line;
    while (std::getline(in, line)) {
        if (line.empty()) continue;
        size_t p1 = line.find(" | ");
        if (p1 == std::string::npos) continue;
        size_t p2 = line.find(" | ", p1 + 3);
        if (p2 == std::string::npos) continue;
        Message m;
        m.time = line.substr(0, p1);
        m.sender = line.substr(p1 + 3, p2 - p1 - 3);
        m.text = line.substr(p2 + 3);
        out.push_back(m);
    }
    return out;
}

void appendMessage(const std::string& user, const std::string& friendName, const Message& m) {
    ensureDir(user);
    std::ofstream out(historyPath(user, friendName), std::ios::app);
    out << m.time << " | " << m.sender << " | " << m.text << "\n";
}

void clearHistory(const std::string& user, const std::string& friendName) {
    std::ofstream out(historyPath(user, friendName), std::ios::trunc);
    out << "";
}

std::vector<std::string> loadBotReplies() {
    std::string content = readFile("data/scripts/bot_replies.json");
    std::vector<std::string> out;
    size_t i = 0;
    while (i < content.size()) {
        if (content[i] == '"') {
            ++i;
            std::string s;
            while (i < content.size() && content[i] != '"') {
                if (content[i] == '\\' && i + 1 < content.size()) ++i;
                s.push_back(content[i]);
                ++i;
            }
            ++i;
            out.push_back(s);
        } else {
            ++i;
        }
    }
    return out;
}

namespace {

void printPage(const std::string& user, const std::string& friendName, int page) {
    std::vector<Message> all = loadHistory(user, friendName);
    if (page < 1) page = 1;
    int skip = (page - 1) * 10;
    int printed = 0;
    for (int i = static_cast<int>(all.size()) - 1; i >= 0 && printed < 10; --i) {
        if (skip > 0) { --skip; continue; }
        std::cout << all[i].time << " | " << all[i].sender << " | " << all[i].text << "\n";
        ++printed;
    }
    if (printed == 0) std::cout << "(no messages)\n";
}

std::string nextReply(const std::vector<std::string>& replies, size_t index) {
    if (replies.empty()) return "...";
    return replies[index % replies.size()];
}

}  // namespace

void runSession(const std::string& user, const std::string& friendName) {
    std::vector<std::string> replies = loadBotReplies();
    size_t replyIndex = 0;
    while (true) {
        std::cout << "> " << std::flush;
        std::string line;
        if (!std::getline(std::cin, line)) break;
        if (!stdinIsTerminal()) std::cout << line << "\n";

        if (line == "/exit" || line == "/back") break;
        if (line.rfind("/history", 0) == 0) {
            int page = 1;
            size_t sp = line.find(' ');
            if (sp != std::string::npos) page = std::atoi(line.c_str() + sp + 1);
            printPage(user, friendName, page);
            continue;
        }
        if (line == "/clear") {
            clearHistory(user, friendName);
            std::cout << "History cleared\n";
            continue;
        }

        Message um;
        um.time = nowIso8601();
        um.sender = user;
        um.text = line;
        appendMessage(user, friendName, um);

        std::string reply = nextReply(replies, replyIndex++);
        Message bm;
        bm.time = nowIso8601();
        bm.sender = "Bot";
        bm.text = reply;
        appendMessage(user, friendName, bm);

        std::cout << "[Bot] " << reply << "\n";
    }
}

std::vector<Message> simulate(const std::string& user, const std::string& friendName,
                              const std::vector<std::string>& inputs) {
    clearHistory(user, friendName);
    std::vector<std::string> replies = loadBotReplies();
    std::vector<Message> all;
    size_t replyIndex = 0;
    for (const std::string& input : inputs) {
        Message um;
        um.time = nowIso8601();
        um.sender = user;
        um.text = input;
        appendMessage(user, friendName, um);
        all.push_back(um);

        std::string reply = nextReply(replies, replyIndex++);
        Message bm;
        bm.time = nowIso8601();
        bm.sender = "Bot";
        bm.text = reply;
        appendMessage(user, friendName, bm);
        all.push_back(bm);
    }
    return all;
}

}  // namespace chat

