std::string fileFor(const std::string& username) {
    return "data/aliases_" + username + ".json";
}

namespace {

std::string readFile(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

std::string jsonEscape(const std::string& s) {
    std::string out;
    for (char c : s) {
        if (c == '"' || c == '\\') out.push_back('\\');
        out.push_back(c);
    }
    return out;
}

}  // namespace

std::vector<Alias> list(const std::string& username) {
    std::string content = readFile(fileFor(username));
    std::vector<Alias> result;
    size_t i = 0;
    while (i < content.size()) {
        size_t k1 = content.find('"', i);
        if (k1 == std::string::npos) break;
        size_t k2 = content.find('"', k1 + 1);
        if (k2 == std::string::npos) break;
        size_t colon = content.find(':', k2 + 1);
        if (colon == std::string::npos) break;
        size_t v1 = content.find('"', colon + 1);
        if (v1 == std::string::npos) break;
        size_t v2 = content.find('"', v1 + 1);
        if (v2 == std::string::npos) break;
        Alias a;
        a.friendName = content.substr(k1 + 1, k2 - k1 - 1);
        a.alias = content.substr(v1 + 1, v2 - v1 - 1);
        result.push_back(a);
        i = v2 + 1;
    }
    return result;
}

void save(const std::string& username, const std::vector<Alias>& entries) {
    std::ofstream out(fileFor(username), std::ios::trunc);
    out << "{";
    for (size_t i = 0; i < entries.size(); ++i) {
        if (i) out << ",";
        out << "\n  \"" << jsonEscape(entries[i].friendName) << "\": \""
            << jsonEscape(entries[i].alias) << "\"";
    }
    if (!entries.empty()) out << "\n";
    out << "}\n";
}

void set(const std::string& username, const std::string& friendName,
         const std::string& alias) {
    std::vector<Alias> entries = list(username);
    bool found = false;
    for (Alias& a : entries) {
        if (a.friendName == friendName) {
            a.alias = alias;
            found = true;
        }
    }
    if (!found) entries.push_back(Alias{friendName, alias});
    save(username, entries);
}

std::string resolve(const std::string& username, const std::string& friendName) {
    for (const Alias& a : list(username)) {
        if (a.friendName == friendName) return a.alias;
    }
    return friendName;
}

}  // namespace aliases

