    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

std::string toLower(const std::string& s) {
    std::string out = s;
    for (char& c : out) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    return out;
}

bool findCI(const std::string& hay, const std::string& needle, size_t& at) {
    if (needle.empty()) return false;
    size_t p = toLower(hay).find(toLower(needle));
    if (p == std::string::npos) return false;
    at = p;
    return true;
}

std::string cleanPath(const std::filesystem::path& p) {
    return p.string();
}

}  // namespace

std::vector<Hit> find(const std::string& user, const std::string& keyword) {
    std::vector<Hit> hits;
    if (keyword.empty()) return hits;

    std::error_code ec;
    std::filesystem::path root("data/history");
    if (!std::filesystem::exists(root, ec)) return hits;

    std::filesystem::recursive_directory_iterator it(root, ec);
    std::filesystem::recursive_directory_iterator end;
    for (; it != end && !ec; it.increment(ec)) {
        if (!it->is_regular_file(ec)) continue;
        if (it->path().extension() != ".log") continue;

        std::string friendName = it->path().stem().string();
        std::string display = aliases::resolve(user, friendName);

        std::istringstream in(readFile(cleanPath(it->path())));
        std::string line;
        while (std::getline(in, line)) {
            if (line.empty()) continue;
            std::string date;
            std::string text = line;
            size_t p1 = line.find(" | ");
            if (p1 != std::string::npos) {
                date = line.substr(0, p1);
                text = line.substr(p1 + 3);
                size_t p2 = text.find(" | ");
                if (p2 != std::string::npos) text = text.substr(p2 + 3);
            }
            size_t at = 0;
            if (!findCI(text, keyword, at)) continue;

            Hit h;
            h.friendName = display;
            h.date = date;
            h.snippet = text.substr(0, at) + "[[" +
                        text.substr(at, keyword.size()) + "]]" +
                        text.substr(at + keyword.size());
            hits.push_back(h);
        }
    }
    return hits;
}

void print(const std::string& user, const std::string& keyword) {
    std::vector<Hit> hits = find(user, keyword);
    for (const Hit& h : hits) {
        std::cout << "[" << h.friendName << "] " << h.date << " | " << h.snippet
                  << "\n";
    }
    if (hits.empty()) std::cout << "(no matches)\n";
}

}  // namespace search

