namespace concurrency {

template <class T>
class ThreadSafeQueue {
public:
    void push(const T& value) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            items_.push_back(value);
        }
        cond_.notify_one();
    }

    bool pop(T& out) {
        std::unique_lock<std::mutex> lock(mutex_);
        cond_.wait(lock, [this] { return !items_.empty() || closed_; });
        if (items_.empty()) return false;
        out = items_.front();
        items_.pop_front();
        return true;
    }

    bool tryPop(T& out) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (items_.empty()) return false;
        out = items_.front();
        items_.pop_front();
        return true;
    }

    bool empty() {
        std::lock_guard<std::mutex> lock(mutex_);
        return items_.empty();
    }

    size_t size() {
        std::lock_guard<std::mutex> lock(mutex_);
        return items_.size();
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        cond_.notify_all();
    }

private:
    std::mutex mutex_;
    std::condition_variable cond_;
    std::deque<T> items_;
    bool closed_ = false;
};

struct Incoming {
    std::string friendName;
    std::string text;
};

enum class ReadResult { Line, None, Eof };

void startSimulator(const std::string& user, const std::vector<std::string>& friends);
void stopSimulator();
std::vector<Incoming> drainMessages();

ReadResult tryReadLine(std::string& line);

size_t pump(const std::string& prompt);

