#include "concurrency.hpp"

#include "chat.hpp"

#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <random>
#include <thread>

#if !defined(_WIN32)
#include <sys/select.h>
#include <unistd.h>
#endif

namespace concurrency {

namespace {

std::vector<std::thread> g_threads;
std::atomic<bool> g_running{false};
ThreadSafeQueue<Incoming> g_queue;

const char* const kSamples[] = {
    "hey, you around?",
    "ping",
    "what's up?",
    "did you see that?",
    "brb",
    "how's it going?",
};
const size_t kSampleCount = sizeof(kSamples) / sizeof(kSamples[0]);

void sleepMs(int ms) {
    std::this_thread::sleep_for(std::chrono::milliseconds(ms));
}

int randomBetween(int lo, int hi) {
    static thread_local std::mt19937 rng(
        static_cast<unsigned>(std::chrono::steady_clock::now().time_since_epoch().count()) ^
        std::hash<std::thread::id>{}(std::this_thread::get_id()));
    std::uniform_int_distribution<int> dist(lo, hi);
    return dist(rng);
}

void producer(const std::string& user, const std::string& friendName, int loMs, int hiMs,
              std::atomic<int>* counter) {
    while (g_running.load()) {
        sleepMs(randomBetween(loMs, hiMs));
        if (!g_running.load()) break;
        std::string text = kSamples[static_cast<size_t>(randomBetween(0, static_cast<int>(kSampleCount) - 1))];
        g_queue.push(Incoming{friendName, text});
        if (counter) counter->fetch_add(1);
        chat::Message m;
        m.time = chat::nowIso8601();
        m.sender = friendName;
        m.text = text;
        chat::appendMessage(user, friendName, m);
    }
}

}  // namespace

void startSimulator(const std::string& user, const std::vector<std::string>& friendList) {
    stopSimulator();
    g_running.store(true);
    for (const std::string& f : friendList) {
        g_threads.emplace_back(producer, user, f, 3000, 6000, nullptr);
    }
}

void stopSimulator() {
    g_running.store(false);
    for (std::thread& t : g_threads) {
        if (t.joinable()) t.join();
    }
    g_threads.clear();
    Incoming discard;
    while (g_queue.tryPop(discard)) {}
}

std::vector<Incoming> drainMessages() {
    std::vector<Incoming> out;
    Incoming item;
    while (g_queue.tryPop(item)) out.push_back(item);
    return out;
}

size_t pump(const std::string& prompt) {
    std::vector<Incoming> msgs = drainMessages();
    for (const Incoming& m : msgs) {
        std::cout << "\n[" << m.friendName << "] " << m.text << "\n";
    }
    if (!msgs.empty()) std::cout << prompt << std::flush;
    return msgs.size();
}

ReadResult tryReadLine(std::string& line) {
    if (std::cin.rdbuf()->in_avail() <= 0) {
#if defined(_WIN32)
        // Windows fallback: blocking read.
#else
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(STDIN_FILENO, &fds);
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 0;
        int ready = select(STDIN_FILENO + 1, &fds, nullptr, nullptr, &tv);
        if (ready <= 0 || !FD_ISSET(STDIN_FILENO, &fds)) return ReadResult::None;
#endif
    }
    if (!std::getline(std::cin, line)) {
        line.clear();
        return ReadResult::Eof;
    }
    return ReadResult::Line;
}

int selftest(int seconds) {
    g_running.store(true);
    std::atomic<int> produced{0};
    std::vector<std::thread> producers;
    const char* friends[] = {"alpha", "beta"};
    for (const char* f : friends) {
        producers.emplace_back(producer, std::string("selftest"), std::string(f), 200, 500, &produced);
    }

    int processed = 0;
    std::chrono::steady_clock::time_point deadline =
        std::chrono::steady_clock::now() + std::chrono::seconds(seconds);
    while (std::chrono::steady_clock::now() < deadline) {
        processed += static_cast<int>(drainMessages().size());
        sleepMs(20);
    }

    g_running.store(false);
    for (std::thread& t : producers) {
        if (t.joinable()) t.join();
    }
    processed += static_cast<int>(drainMessages().size());

    std::cout << "{\"processed\": " << processed << "}" << std::endl;
    return 0;
}

}  // namespace concurrency

