        if (!promptShown) {
            std::cout << "Action: " << std::flush;
            promptShown = true;
        }
        if (concurrency::pump("Action: ") > 0) promptShown = true;

        std::string action;
        concurrency::ReadResult r = concurrency::tryReadLine(action);
        if (r == concurrency::ReadResult::Eof) break;
        if (r == concurrency::ReadResult::None) {
            std::this_thread::sleep_for(std::chrono::milliseconds(30));
            continue;
        }
        promptShown = false;

        if (action == "A" || action == "a") {
            std::string name = prompt("Username: ");
            if (friends::add(username, name)) {
                std::cout << "Friend added\n";
                restartSim();
            } else {
                std::cout << "Friend already exists\n";
            }
        } else if (action == "R" || action == "r") {
            std::string name = prompt("Username: ");
            if (friends::remove(username, name)) {
                std::cout << "Friend removed\n";
                restartSim();
            } else {
                std::cout << "Friend not found\n";
            }
        } else if (action == "L" || action == "l") {
            std::vector<friends::Friend> entries = friends::list(username);
            if (entries.empty()) {
                std::cout << "No friends\n";
            }
            for (const friends::Friend& f : entries) {
                std::cout << "  - " << aliases::resolve(username, f.user)
                          << " [" << f.status << "]\n";
            }
        } else if (action == "C" || action == "c") {
            std::string name = prompt("Friend ID: ");
            std::cout << "--- Chat with " << aliases::resolve(username, name)
                      << " ---\n";
            chat::runSession(username, name);
        } else if (action == "Q" || action == "q") {
            concurrency::stopSimulator();
            std::cout << "Logged out\n";
            return;
        } else if (action.rfind("set-alias ", 0) == 0) {
            std::string rest = action.substr(10);
            size_t sp = rest.find(' ');
            if (sp == std::string::npos || sp == 0 || sp + 1 >= rest.size()) {
                std::cout << "Usage: set-alias <friend> <alias>\n";
            } else {
                aliases::set(username, rest.substr(0, sp), rest.substr(sp + 1));
                std::cout << "Alias set\n";
            }
        } else if (action.rfind("/search", 0) == 0) {
            std::string keyword = action.size() > 8 ? action.substr(8) : "";
            search::print(username, keyword);
        } else {
            std::cout << "Invalid choice\n";
        }
    }
    concurrency::stopSimulator();
}

