#include "concurrency.hpp"

#include <atomic>
#include <cassert>
#include <cstdio>
#include <thread>
#include <vector>

using concurrency::ThreadSafeQueue;

static void testFifo() {
    ThreadSafeQueue<int> q;
    for (int i = 1; i <= 5; ++i) q.push(i);
    assert(q.size() == 5);
    for (int i = 1; i <= 5; ++i) {
        int out = -1;
        assert(q.pop(out));
        assert(out == i);
    }
    assert(q.empty());
    int out = -1;
    assert(!q.tryPop(out));
}

static void testThreadSafety() {
    ThreadSafeQueue<int> q;
    const int producers = 4;
    const int consumers = 3;
    const int perProducer = 1000;
    const int total = producers * perProducer;

    std::atomic<long long> sum{0};
    std::atomic<int> count{0};

    std::vector<std::thread> workers;
    for (int c = 0; c < consumers; ++c) {
        workers.emplace_back([&q, &sum, &count] {
            int v = 0;
            while (q.pop(v)) {
                sum.fetch_add(v);
                count.fetch_add(1);
            }
        });
    }
    for (int p = 0; p < producers; ++p) {
        workers.emplace_back([&q, p, perProducer] {
            for (int i = 0; i < perProducer; ++i) q.push(p * perProducer + i);
        });
    }
    for (std::thread& t : workers) {
        if (t.get_id() != std::this_thread::get_id()) t.join();
    }
    q.close();
    for (std::thread& t : workers) {
        if (t.joinable()) t.join();
    }

    assert(count.load() == total);

    long long expected = static_cast<long long>(total - 1) * total / 2;
    assert(sum.load() == expected);
}

int main() {
    testFifo();
    std::printf("FIFO order: OK\n");

    testThreadSafety();
    std::printf("Thread safety (no loss, no corruption): OK\n");

    std::printf("All queue assertions passed\n");
    return 0;
}

