    for (int p = 0; p < producers; ++p) {
        producerThreads.emplace_back([&q, p, perProducer] {
            for (int i = 0; i < perProducer; ++i) q.push(p * perProducer + i);
        });
    }

    for (std::thread& t : producerThreads) t.join();
